{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol-rich palm oil fraction, a lipophilic isoprenoid with a polar chromanol head, has poor oral bioavailability in humans, providing affirmative low-F evidence for the analogous polar-headed long-chain isoprenoid CoQ10.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "All-trans lycopene absorption was 12.2 ± 2.1% in humans, below the 20% threshold, indicating that long-chain isoprenoids can have low oral bioavailability; this supports low F for CoQ10 despite low transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a smaller C40 isoprenoid, had an absolute bioavailability of 58.5% in humans, the strongest high-F analogue; however, its lower molecular weight and lack of a quinone head reduce transferability to CoQ10.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C23"],
      "claim": "Cis-lycopene showed 24.5% bioavailability in a labeled human study, marginally above the 20% threshold, but this is an outlier relative to other lycopene measurements and comes from a smaller carotenoid.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a prenylated phloroglucinol, showed high oral bioavailability, but it is smaller and was administered as an extract, so it is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is coenzyme Q10, a very large (MW 863), highly lipophilic ubiquinone with a decaprenyl side chain. Although phytoene and cis-lycopene provide high-F data for smaller C40 isoprenoids, the much higher molecular weight, extreme logP, and presence of a quinone head make CoQ10 more comparable to the poorly absorbed tocotrienol and to the low systemic-availability lycopene measurements. Affirmative low-F evidence from tocotrienol and all-trans lycopene, together with the physicochemical liabilities, supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for CoQ10 or a close ubiquinone analogue.",
    "The most transferable high-F analogue (phytoene) is a smaller hydrocarbon carotenoid, not a quinone.",
    "Low-F lycopene records are mostly systemic availability rather than absolute F and have low transferability.",
    "Formulation and food-matrix effects are not captured; CoQ10 formulations might improve absorption."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C04"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "carotenoid isoprenoids (phytoene)"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C23"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "carotenoid isoprenoids (lycopene cis)"
    },
    {
      "applicability": "low",
      "card_ids": ["C24"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "carotenoid isoprenoids (lycopene all-trans)"
    },
    {
      "applicability": "low",
      "card_ids": ["C13"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "prenylated phenols (tocotrienol)"
    },
    {
      "applicability": "low",
      "card_ids": ["C11"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "prenylated phenols (hyperforin)"
    }
  ],
  "revision_action": "initial"
}

